using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp.Admin { public partial class SettingsPage : WamoApp.AdminPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetList() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Settings", "View"); return AdminDataService.GetList("Settings"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetDefinition() { SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Settings", "View"); return AdminDataService.GetDefinitionMetadata("Settings"); } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object DeleteRecord(string id) { SecurityHelper.ValidateCsrfOrThrow(); SessionManager.RequireAuthenticated(); PermissionManager.DemandPermission("Settings", "Delete"); return AdminDataService.Delete("Settings", id); } } }
